 * Render one list item to its lines: one line when it has no children, otherwise its own
 * text, the nested `<ul>` on its own lines, and a closing `</li>` on its own line.
 * @param {{text: string, items: object[]}} item - the item.
 * @param {Map<string, {url: string, source: string}>} definitions - the link definitions in force.
 * @returns {string[]} the item's lines.
 */
function renderItem(item, definitions) {
  const text = renderInline(item.text, definitions)
  if (item.items.length === 0) return [`<li>${text}</li>`]
  return [`<li>${text}`, ...renderList(item.items, definitions), '</li>']
}

