/** The command: `html`, `outline`, and `defs`, each over the document on standard input. */

import { readFileSync } from 'node:fs'
import { BlockError, headings, parse, render, splitLines } from './block.js'
import { DEFINITION, normalizeLabel } from './labels.js'

const USAGE = 'usage: cli.js html|outline|defs [<definitions>]'
const MODES = ['html', 'outline', 'defs']

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
const mode = argv[0]
if (!MODES.includes(mode) || argv.length < 1 || argv.length > 2) fail(USAGE)

const definitionsPath = argv[1]
const definitions = new Map()

if (definitionsPath !== undefined) {
  let text
  try {
    text = readFileSync(definitionsPath, 'utf8')
  } catch {
    fail(`cannot read definitions ${definitionsPath}`)
  }
  const fileLines = splitLines(text)
  for (let index = 0; index < fileLines.length; index += 1) {
    const trimmed = fileLines[index].trim()
    const line = index + 1
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const match = DEFINITION.exec(trimmed)
    if (match === null) fail(`${definitionsPath}: line ${line}: expected [label]: <url>`)
    const label = normalizeLabel(match[1])
    if (definitions.has(label)) fail(`${definitionsPath}: line ${line}: label ${label} is defined twice`)
    definitions.set(label, { url: match[2], source: 'file' })
  }
}

let parsed
try {
  parsed = parse(splitLines(readFileSync(0, 'utf8')), definitions)
} catch (error) {
  if (!(error instanceof BlockError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

if (mode === 'html') {
  process.stdout.write(render(parsed, definitions))
} else if (mode === 'outline') {
  process.stdout.write(headings(parsed).map(one => `${one.level} ${one.text}\n`).join(''))
} else {
  const rows = [...definitions.entries()].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  const lines = rows.map(([label, definition]) => `${label} ${definition.url} ${definition.source}\n`)
  lines.push(`total ${rows.length}\n`)
  process.stdout.write(lines.join(''))
}
"}

